"""Generate the requested handover report only from completed measured JSON artifacts."""
from pathlib import Path
import json,datetime
ROOT=Path(__file__).resolve().parents[1]
r=json.loads((ROOT/'tests/phase6-performance.json').read_text(encoding='utf-8'));b=json.loads((ROOT/'tests/phase6-backup-restore.json').read_text(encoding='utf-8'))
misses=[name for group in ['timings','phase6_timings'] for name,value in r[group].items() if not value['target_met']]
out=['# Performance benchmark report','', '12 November 2026. Actual local execution, synthetic data, freshly migrated disposable PostgreSQL database. No production capacity or SLA guarantee.','', '## Acceptance outcome','',('**LOCAL TARGETS NOT ALL MET.** Failed local p95 objectives: '+', '.join(misses)+'. Keep the performance release gate blocked.' if misses else 'All documented local read targets met. Deployment-specific acceptance remains blocked.'),'','Phase 6 read target: p95 below 5,000 ms. Existing finance read target retained at 2,000 ms. Thresholds were not raised to hide misses. The benchmark writes its complete artifact before asserting targets; a nonzero exit caused by these misses is an honest failed performance gate, not a missing report.','','## Hardware and method','']
for key,value in r['hardware'].items():out.append('- '+key+': '+str(value))
out+=['','Thirty warm authenticated HTTP samples per route after warm-up. p50 is median, p95/p99 use 30-sample order statistics (p99 is the sample maximum). This is a Development-mode HTTP baseline with current cookies/CSRF, preserved rate limits and synthetic independent reviewer accounts; it does not include deployed TLS/proxy/MFA/provider latency. Local developer/background processes were present. CPU/RSS refer only to the API process; PostgreSQL/whole-host peaks were not measured. Cold starts, sustained production concurrency and long-running tail/error budgets are not certified.','','## Asserted fixture dimensions','']
for key,value in r['scenario'].items():out.append('- '+key+': '+format(value,','))
out+=['','The main tenant has 100,000 memberships across 10,000 chapters; the remaining tenants extend global organization totals. This is not a uniform 100,000-members-per-society test. Large accounting/activity/message datasets are direct SQL synthetic fixtures with integrity triggers enabled; these are not claimed as API write or real delivery throughput. Default bulk-selection timing scans the 100,000-row membership dataset with the Active filter; it does not mean all 100,000 rows were selected or rendered. Actual rendering is measured separately.','','## Authenticated finance read latency','']
for name,v in r['timings'].items():out.append('- '+name+': p50 '+str(v['p50_ms'])+' ms; p95 '+str(v['p95_ms'])+' ms; p99 '+str(v['p99_ms'])+' ms; target '+('PASS' if v['target_met'] else 'FAIL')+'.')
out+=['','## Phase 6 read latency','']
for name,v in r['phase6_timings'].items():out.append('- '+name+': p50 '+str(v['p50_ms'])+' ms; p95 '+str(v['p95_ms'])+' ms; p99 '+str(v['p99_ms'])+' ms; '+str(v['failures'])+'/'+str(v['samples'])+' failures; target '+('PASS' if v['target_met'] else 'FAIL')+'.')
out+=['','## Queue, concurrency and actual documents','']
v=r['annual_billing'];out.append('- Annual billing: '+str(v['processed'])+'/'+str(v['cohort_members'])+' completed in '+str(v['elapsed_ms'])+' ms ('+str(v['invoices_per_second'])+'/s). '+v['scope']+'.')
v=r['concurrent_reads'];out.append('- Overlapping readers: '+str(v['overlapping_readers'])+'; requests '+str(v['requests'])+'; failures '+str(v['failures'])+'; p95 '+str(v['p95_ms'])+' ms.')
for name,v in r['document_generation'].items():out.append('- '+name+': '+json.dumps(v,ensure_ascii=False)+'.')
out+=['','Cards/certificates are actual independently approved durable jobs and 300 DPI server image/PDF output, not counts inferred from SQL. Default templates use text/QR, without photo-heavy or complex-script rendering. The ZIP job really creates the archive; authorized download contents and user-bound links are separately exercised by HTTP integration tests. A 100,000-recipient rendering run, physical printer speed and disaster recovery at this scale were not measured.','','API process metrics: '+json.dumps(r['api_process_metrics'])+'.','','## Representative PostgreSQL plans','']
for name,plan in r['explain_analyze_buffers'].items():
 data=plan[0];node=data['Plan'];out.append('- '+name+': execution '+str(data.get('Execution Time'))+' ms; top node '+str(node.get('Node Type'))+'; actual rows '+str(node.get('Actual Rows'))+'; shared hits '+str(node.get('Shared Hit Blocks'))+'; shared reads '+str(node.get('Shared Read Blocks'))+'.')
out+=['','Full EXPLAIN ANALYZE/BUFFERS trees are in tests/phase6-performance.json. These representative plans are not claimed as complete plans for every dashboard/ageing subquery. Statement-level quota triggers and partial worker indexes remain enabled; integrity was not disabled for speed.','','## Actual encrypted backup and restore','']
v=b['restore'];out+=['- AES-256-GCM encrypted archive: '+str(b['backup']['bytes'])+' bytes.','- Backup '+str(b['backup']['elapsedSeconds'])+' seconds; isolated restore/verification '+str(v['elapsedSeconds'])+' seconds.','- '+str(len(v['tables']))+' tables; all snapshot counts matched; '+str(v['objectFiles'])+' object hashes matched; '+str(v['keyFiles'])+' test key-directory files; unbalanced posted journals '+str(v['unbalancedPostedJournals'])+'.','- Generated verification database dropped afterward. No running database or objects were overwritten. The test used an ephemeral AES key and a marker, not deployed Data Protection secret recovery. Off-host RPO/RTO/PITR remain unverified.','','## Reproducibility and remaining work','','Build the API, then run `python tests/phase6_api_benchmark.py`; optionally select an isolated build through ASSEMBLIA_API_DLL. It creates and drops only its generated benchmark database. Run `python tests/backup_restore_integration.py` for the isolated logical restore drill. Generate this report with `python scripts/phase6_benchmark_report.py` after both artifacts exist. Raw artifacts are the source of the figures, including failures.','', 'The first attempt after the date change lost its fixture session; the harness now renews fixture authentication without weakening application sessions. A subsequent rendering attempt reached 934/1,000 cards with zero record failures but hit an arbitrary 240-second harness wait. The completed run uses a 900-second wait and records actual throughput; the longer wait is not represented as a speed improvement.','','For missed finance targets, capture full scoped dashboard/ageing SQL plans, reduce repeated/large aggregations while preserving legal-entity separation and immutable historical postings, and repeat the scenario on intended launch hardware. Do not mark the release gate passed until measured objectives are accepted. Production concurrency, resource limits, queue fairness, storage cleanup and a representative photo/language/printer campaign remain acceptance work.']
meta=ROOT/'.local/phase6-benchmark-build.json'
if meta.exists():out+=['','Measured API binary SHA-256: `'+json.loads(meta.read_text(encoding='utf-8-sig'))['Hash']+'`. The final functional suite additionally includes nested-null request validation; this benchmark is not claimed as a production release-artifact certification.']
(ROOT/'PERFORMANCE_BENCHMARK_REPORT.md').write_text('\n'.join(out)+'\n',encoding='utf-8');print('Wrote measured performance report; missed targets:',misses)
